static void *view_make(const char *name, uint32_t view, void *parent, void **widget, uint32_t *index) {
	if (strcmp(name, "View") == 0) {
		maps_View *v = maps_make_View((maps_View_events){view, parent});
		if (!v) return NULL;
		*widget = v->widget;
		*index = 0;
		return v;
	}
	return NULL;
}

static void view_set(void *obj, uint32_t index, const char *prop, asuka_reader *r) {
	switch (index) {
	case 0: {
		maps_View *v = obj;
		if (strcmp(prop, "Region") == 0) {
			maps_Region a = r_Region(r);
			if (!r->failed && v->vt->set_region) v->vt->set_region(v, &a);
			maps_Region_free(&a);
			return;
		}
		if (strcmp(prop, "Camera") == 0) {
			maps_Camera a = r_Camera(r);
			if (!r->failed && v->vt->set_camera) v->vt->set_camera(v, &a);
			maps_Camera_free(&a);
			return;
		}
		if (strcmp(prop, "Markers") == 0) {
			maps_list_Marker a = r_list_Marker(r);
			if (!r->failed && v->vt->set_markers) v->vt->set_markers(v, a);
			maps_list_Marker_free(&a);
			return;
		}
		if (strcmp(prop, "Polylines") == 0) {
			maps_list_Polyline a = r_list_Polyline(r);
			if (!r->failed && v->vt->set_polylines) v->vt->set_polylines(v, a);
			maps_list_Polyline_free(&a);
			return;
		}
		if (strcmp(prop, "Polygons") == 0) {
			maps_list_Polygon a = r_list_Polygon(r);
			if (!r->failed && v->vt->set_polygons) v->vt->set_polygons(v, a);
			maps_list_Polygon_free(&a);
			return;
		}
		if (strcmp(prop, "Circles") == 0) {
			maps_list_Circle a = r_list_Circle(r);
			if (!r->failed && v->vt->set_circles) v->vt->set_circles(v, a);
			maps_list_Circle_free(&a);
			return;
		}
		if (strcmp(prop, "Selected") == 0) {
			char *a = asuka_reader_string(r);
			if (!r->failed && v->vt->set_selected) v->vt->set_selected(v, a);
			free(a);
			return;
		}
		if (strcmp(prop, "Clustering") == 0) {
			bool a = asuka_reader_bool(r);
			if (!r->failed && v->vt->set_clustering) v->vt->set_clustering(v, a);
			return;
		}
		if (strcmp(prop, "ClusterColor") == 0) {
			int64_t *a = r_opt_int(r);
			if (!r->failed && v->vt->set_clusterColor) v->vt->set_clusterColor(v, a);
			free(a);
			return;
		}
		if (strcmp(prop, "MapType") == 0) {
			maps_MapType a = asuka_reader_i64(r);
			if (!r->failed && v->vt->set_mapType) v->vt->set_mapType(v, a);
			return;
		}
		if (strcmp(prop, "ShowsUser") == 0) {
			bool a = asuka_reader_bool(r);
			if (!r->failed && v->vt->set_showsUser) v->vt->set_showsUser(v, a);
			return;
		}
		if (strcmp(prop, "Interactive") == 0) {
			bool a = asuka_reader_bool(r);
			if (!r->failed && v->vt->set_interactive) v->vt->set_interactive(v, a);
			return;
		}
		(void)v;
		return;
	}
	}
	(void)prop;
	(void)r;
}

static bool view_measure(void *obj, uint32_t index, float width, float height, float *out_width, float *out_height) {
	switch (index) {
	case 0: {
		maps_View *v = obj;
		return v->vt->measure && v->vt->measure(v, width, height, out_width, out_height);
	}
	}
	return false;
}

static void view_destroy(void *obj, uint32_t index) {
	switch (index) {
	case 0: {
		maps_View *v = obj;
		if (v->vt->destroy) v->vt->destroy(v);
		else free(v);
		return;
	}
	}
}

static const asuka_native_views views = {view_make, view_set, view_measure, view_destroy};

static const asuka_native_provider provider = {
	.path = "platform/maps",
	.make = make,
	.call = call,
	.start = start,
	.release = release,
	.views = &views,
};

ASUKA_NATIVE_CONSTRUCTOR(register_maps) { asuka_native_register(&provider); }
